ow(a){return"\u062a\u062d\u062f\u064a\u062b v"+a},
xS(a,b){return"\u062a\u062d\u062f\u064a\u062b "+(b?"\u062a\u062c\u0631\u064a\u0628\u064a":"\u062c\u062f\u064a\u062f")+": v"+a},
Ap(a){return""+a+" \u0639\u0646\u0635\u0631"},
